// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Validate environment variables
if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
  console.error('Missing Supabase environment variables. Please check your .env file.');
  console.error('Required variables: VITE_SUPABASE_URL, VITE_SUPABASE_PUBLISHABLE_KEY');
  console.error('Current values:', { SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY: SUPABASE_PUBLISHABLE_KEY ? '***' : 'missing' });
} else {
  console.log('✓ Supabase environment variables loaded');
  console.log('Supabase URL:', SUPABASE_URL);
}

if (SUPABASE_PUBLISHABLE_KEY === 'your_supabase_anon_key_here') {
  console.warn('⚠️  Supabase publishable key is still set to placeholder value. Please update your .env file with your actual Supabase key.');
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

// Use fallback values to prevent crashes, but the app won't work properly without real credentials
export const supabase = createClient<Database>(
  SUPABASE_URL || 'https://placeholder.supabase.co',
  SUPABASE_PUBLISHABLE_KEY || 'placeholder-key',
  {
    auth: {
      storage: localStorage,
      persistSession: true,
      autoRefreshToken: true,
    }
  }
);